public sealed record YYTint(
    string Id,
    string Name,
    YYTintColors Light,
    YYTintColors Dark,
    Color PaperAccentLight,
    Color PaperAccentDark,
    Color PlayPlain,
    Color PlayKami,
    Color PlayDark,
    Color PlayKaminight,
    Color PlaySage)
{
    public Color Play(YYPaper paper) => paper.Id switch
    {
        "plain" => PlayPlain,
        "kami" => PlayKami,
        "dark" => PlayDark,
        "kaminight" => PlayKaminight,
        "sage" => PlaySage,
        "eink" => paper.Main,
        _ => paper.IsDark ? PlayDark : PlayPlain,
    };
}

